def canon(sub):
    import numpy as np
    b=sub.astype(bool)
    variants=[b, np.fliplr(b), np.flipud(b), b.T, np.rot90(b), np.rot90(b,2), np.rot90(b,3), np.rot90(b).T]
    return min(tuple(v.ravel()) for v in variants), b.shape
