def canon2(sub):
    b=np.array(sub)!=0
    vs=[b,np.fliplr(b),np.flipud(b),np.rot90(b),np.rot90(b,2),np.rot90(b,3),b.T,np.rot90(b).T]
    return min(tuple(v.ravel()) for v in vs)
def objs2(g,bgs):
    st=ndimage.generate_binary_structure(2,1)
    res=[]
    for c in sorted(np.unique(g)):
        if c in bgs: continue
        lab,n=ndimage.label(g==c,structure=st)
        for i in range(1,n+1):
            ys,xs=np.where(lab==i)
            res.append({'c':int(c),'n':len(ys),'bb':(int(ys.min()),int(ys.max()),int(xs.min()),int(xs.max()))})
    return res
